// Shared @react-pdf/renderer font registration for every downloadable PDF
// in the app (finance/package-summary-pdf.tsx, itinerary/
// itinerary-summary-pdf.tsx, itinerary/map-pdf.tsx) -- explicit user
// request: downloadable files should follow the same two body/label type
// roles the rest of the app uses (src/app/layout.tsx's --font-sans/
// --font-mono), not react-pdf's built-in Helvetica default. Deliberately
// excludes role 1 (Big Shoulders Stencil Display) -- that's a headline
// face reserved for on-screen h1/h2/h3, and the user's own request named
// only roles 2 and 3.
//
// These are NOT Google's own served CSS2 font files -- a real bug found
// while building this: Google's font-serving backend hands a modern
// (variable-font-capable) client a single file shared across every
// requested static weight for Archivo's Latin range (confirmed: identical
// URL for wght 400/600/700), i.e. a font that still carries composite/
// variation-derived glyph structure. Embedding that file with a
// real multi-string document (the actual French cost-summary labels, not
// a short smoke-test string) crashed @react-pdf's fontkit-based subsetter
// with "RangeError: Offset is outside the bounds of the DataView" in
// TTFSubset._addGlyph -- a real fontkit 2.0.4 limitation (already latest;
// no newer release fixes it) with that glyph structure, not a
// misconfiguration on this app's side. Fixed by instantiating genuinely
// static TTFs from Google's own upstream variable-font source
// (github.com/google/fonts, Archivo[wdth,wght].ttf) via fonttools'
// varLib.instancer (wght pinned to 400/700, wdth 100), then subsetting to
// the Latin-1 + common-punctuation range every PDF label/booking-reference
// string in this app actually uses (fontTools.subset) -- confirmed against
// the real French label set with no crash and correct glyph rendering.
// Special Elite has no variable version upstream, so its file is that
// same subsetting step applied directly to Google's own static build
// (apache/specialelite/SpecialElite-Regular.ttf -- Apache-2.0 licensed,
// not OFL like Archivo).
//
// Embedded as base64 data URLs rather than a filesystem path: @react-pdf/
// font's own FontSource._load() does its own internal fontkit.open(path)
// for a plain path string, a dynamic fs call buried in node_modules that
// Next's Vercel output-file-tracer has no way to discover -- the asset
// would silently go missing from the serverless bundle in production
// while still working locally. A data: URL is decoded in-memory
// (FontSource._load's isDataUrl branch) with no filesystem/network call at
// all, so there's nothing for the tracer to miss and nothing to degrade
// at request time (charter rule 8) -- the exact same self-hosting
// precedent as src/app/fonts/big-shoulders-stencil-display.woff2 (DR-156).
import { Font } from '@react-pdf/renderer';

export const PDF_FONT_BODY = 'Archivo';
export const PDF_FONT_CODE = 'Special Elite';

const ARCHIVO_REGULAR =
  'data:font/ttf;base64,';
const ARCHIVO_BOLD =
  'data:font/ttf;base64,';
const SPECIAL_ELITE_REGULAR =
  'data:font/ttf;base64,';

let registered = false;

/** Idempotent -- safe to call from every PDF-rendering function; Font.register
 * just re-registers the same family/weight pair on a repeat call, but this
 * guard avoids redoing the (cheap but pointless) base64 decode on every
 * PDF generated within one warm serverless instance. */
export function registerPdfFonts(): void {
  if (registered) return;
  registered = true;
  Font.register({
    family: PDF_FONT_BODY,
    fonts: [
      { src: ARCHIVO_REGULAR, fontWeight: 400 },
      { src: ARCHIVO_BOLD, fontWeight: 700 },
    ],
  });
  Font.register({
    family: PDF_FONT_CODE,
    fonts: [{ src: SPECIAL_ELITE_REGULAR, fontWeight: 400 }],
  });
}
